fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> Vec<i8> {
    // Verify j is within column bounds
    assert!(j < m, "Column index j must be less than m");
    
    let mut column = Vec::with_capacity(n);
    
    for i in 0..n {
        // Verify each row has exactly m columns
        assert!(input[i].len() == m, "Each row must have exactly m columns");
        column.push(input[i][j]);
    }
    
    column
}

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> Vec<Vec<i8>> {
    // Verify input dimensions
    assert!(n > 0, "Matrix must have at least one row");
    assert!(input.len() == n, "Input must have exactly n rows");
    
    let mut result = Vec::with_capacity(m);
    
    for j in 0..m {
        let column = get_column(&input, j, m, n);
        result.push(column);
    }
    
    result
}